        let board = Board::new();
        board.join(1, 0);
        board.join(2, 0);
        let start = Arc::new(Barrier::new(8));
        let workers: Vec<_> = (0..8)
            .map(|worker| {
                let board = board.clone();
                let start = start.clone();
                thread::spawn(move || {
                    start.wait();
                    for _ in 0..10_000 {
                        board.award(worker % 2 + 1, 1);
                    }
                })
            })
            .collect();
        for worker in workers {
            worker.join().unwrap();
        }
        assert_eq!(board.score(1), 40_000);
        assert_eq!(board.score(2), 40_000);
        assert_eq!(board.total(), 80_000);
    }

